394	    #[case::negative_zero_in_the_earlier_file(with_final_score("a.ts", -0.0), with_final_score("b.ts", 0.0))]
395	    fn best_first_treats_negative_zero_as_equal_to_zero(#[case] first: RankedBlock, #[case] second: RankedBlock) {
396	        let mut ranked = [first, second];
397	        ranked.sort_by(best_first);
398	        let files: Vec<_> = ranked.iter().map(|r| r.block.file.as_str()).collect();
399	        assert_eq!(files, ["a.ts", "b.ts"]);
400	    }
401	
402	    #[test]
403	    fn best_first_orders_higher_scores_first_and_nan_by_total_order() {
404	        let mut ranked = [
405	            with_final_score("a.ts", -1.0),
406	            with_final_score("b.ts", f64::NAN),
407	            with_final_score("c.ts", 2.0),
408	            with_final_score("d.ts", 0.0),
409	        ];
410	        ranked.sort_by(best_first);
411	        let files: Vec<_> = ranked.iter().map(|r| r.block.file.as_str()).collect();
412	        assert_eq!(files, ["b.ts", "c.ts", "d.ts", "a.ts"]);
413	    }
414	
415	    #[test]
416	    fn rank_blocks_uses_the_input_as_its_corpus() {
417	        // One block: corpus size 1, average length 4. ln((1 - 1 + 0.5) / (1 + 0.5) + 1) * (2 * 2.5) / (2 + 1.5) = 0.410974,
418	        // and the final score is round6(0.410974 * 1.5 + 0.0).
419	        let blocks = vec![(block("a.ts", 1, 1, SymbolKind::Function, vec![]), tokens(&["foo", "foo", "bar", "baz"]))];
420	        let df = HashMap::from([("foo".to_string(), 1)]);
421	        let ranked = rank_blocks(blocks, &["foo"], &df);
422	        let scores: Vec<_> = ranked.iter().map(|r| (r.bm25_score, r.coverage_boost, r.final_score, r.rank)).collect();
423	        assert_eq!(scores, [(0.410_974, 0.0, 0.616_461, 1)]);
424	    }
425	
426	    #[test]
427	    fn rank_blocks_lifts_a_block_whose_name_holds_the_query_terms_over_one_that_only_repeats_them() {
428	        // Both terms have document frequency 2 in a corpus of 2, and the average length is (2 + 7) / 2 = 4.5.
429	        // bm25: the named block 0.437572, the repeating block 0.556235, so without the name multiplier the
430	        // repeating block wins. The name holds both terms, so the multiplier is 3.0 and the named block scores
431	        // round6(0.437572 * 3.0 * 1.5) = 1.969074 against round6(0.556235 * 1.0 * 1.5) = 0.834353.
432	        let function = |file: &str, code: &str| {
433	            let mut b = block(file, 1, 3, SymbolKind::Function, vec![]);
434	            b.code = code.to_string();
435	            b
436	        };
437	        let blocks = vec![
438	            (
439	                function("a.ts", "function load() { parse(); config(); }"),
440	                tokens(&["parse", "parse", "parse", "config", "config", "config", "load"]),
441	            ),
442	            (function("b.ts", "function parseConfig() {}"), tokens(&["parse", "config"])),
443	        ];
444	        let df = HashMap::from([("parse".to_string(), 2), ("config".to_string(), 2)]);
445	        let ranked = rank_blocks(blocks, &["parse", "config"], &df);
446	        let scores: Vec<_> =
447	            ranked.iter().map(|r| (r.block.file.as_str(), r.bm25_score, r.final_score, r.rank)).collect();
448	        assert_eq!(scores, [("b.ts", 0.437_572, 1.969_074, 1), ("a.ts", 0.556_235, 0.834_353, 2)]);
449	    }
450	
451	    /// Calls `visit` once per ordering of `items[k..]`.
452	    fn for_each_permutation<T>(items: &mut [T], k: usize, visit: &mut impl FnMut(&[T])) {
453	        if k == items.len() {
454	            visit(items);
455	            return;
456	        }
457	        for i in k..items.len() {
458	            items.swap(k, i);
459	            for_each_permutation(items, k + 1, visit);
460	            items.swap(k, i);
461	        }
462	    }
463	
464	    #[test]
465	    fn rank_blocks_orders_negative_scores_below_zero() {
466	        // A term in more documents than the corpus holds has a negative IDF, so its score sinks below a non-match.
467	        let blocks = vec![
468	            (block("a.ts", 1, 1, SymbolKind::Function, vec![]), tokens(&["common"])),
469	            (block("b.ts", 1, 1, SymbolKind::Function, vec![]), tokens(&["other"])),
470	        ];
471	        let df = HashMap::from([("common".to_string(), 9)]);
472	        let ranked = rank_blocks(blocks, &["common"], &df);
473	        let scores: Vec<_> = ranked.iter().map(|r| (r.block.file.as_str(), r.bm25_score, r.final_score)).collect();
474	        assert_eq!(scores, [("b.ts", 0.0, 0.0), ("a.ts", -1.15268, -1.72902)]);
475	    }
476	}
