///     line_start: 10,
///     line_end: 20,
///     node_kind: SymbolKind::Function,
///     code: String::new(),
///     symbol_signature: None,
///     matched_lines: vec![12, 30, 40],
///     matched_keywords: Vec::new(),
///     parent: None,
/// };
