1	//! Ranks code blocks by BM25 relevance, boosted by symbol kind, by query terms in the declared name and by how many
2	//! matched lines each block covers.
3	
4	mod bm25;
5	mod boost;
6	mod tokenize_doc;
7	
8	use std::cmp::Ordering;
9	use std::collections::HashMap;
10	use std::hash::BuildHasher;
11	
12	pub use bm25::{round6, score};
13	pub use boost::{coverage_boost, name_match_boost, node_type_boost};
14	pub use tokenize_doc::tokenize_block;
15	
16	use crate::types::{CodeBlock, RankedBlock, SymbolKind};
17	
18	/// Scores each block against `query_terms` and returns them best first, with 1-based ranks.
19	///
20	/// Each block comes with its document tokens, usually from [`tokenize_block`]. The corpus for BM25 is `blocks`
21	/// itself: its size and average token count feed [`score`], and `df` gives each term's document frequency. A block's
22	/// `final_score` is `round6(bm25 * node_type_boost + coverage_boost)`, and its `parent` becomes the ranked block's
23	/// `parent_context`.
24	///
25	/// The order is `final_score` descending (with `-0.0` equal to `0.0`), then ascending `file` by path components,
26	/// `line_start`, `line_end`, `node_kind` in `SymbolKind` declaration order, and `code` by bytes. Reordering the input
27	/// never reorders the output, except that blocks equal on all six keys keep their relative input order.
28	///
29	/// # Examples
30	///
31	/// ```
32	/// use std::collections::HashMap;
33	///
34	/// use camino::Utf8PathBuf;
35	/// use monokl::rank::{rank_blocks, tokenize_block};
36	/// use monokl::types::{CodeBlock, SymbolKind};
37	///
38	/// let block = |file: &str, code: &str| CodeBlock {
39	///     file: Utf8PathBuf::from(file),
40	///     line_start: 1,
41	///     line_end: 1,
42	///     node_kind: SymbolKind::Function,
43	///     code: code.to_string(),
44	///     symbol_signature: None,
45	///     matched_lines: Vec::new(),
46	///     matched_keywords: Vec::new(),
47	///     parent: None,
48	/// };
49	/// let blocks: Vec<_> = [block("b.ts", "parseConfig()"), block("a.ts", "readFile()")]
50	///     .into_iter()
51	///     .map(|b| {
52	///         let tokens = tokenize_block(&b);
53	///         (b, tokens)
54	///     })
55	///     .collect();
56	/// let df = HashMap::from([("config".to_string(), 1)]);
57	///
58	/// let ranked = rank_blocks(blocks, &["config"], &df);
59	/// assert_eq!(ranked[0].block.file, "b.ts");
60	/// assert_eq!(ranked[0].rank, 1);
61	/// assert_eq!(ranked[1].final_score, 0.0);
62	/// ```
63	pub fn rank_blocks<S: BuildHasher>(
64	    blocks: Vec<(CodeBlock, Vec<String>)>,
65	    query_terms: &[&str],
66	    df: &HashMap<String, usize, S>,
67	) -> Vec<RankedBlock> {
68	    if blocks.is_empty() {
69	        return Vec::new();
70	    }
71	    let corpus_size = blocks.len();
72	    let total_tokens: usize = blocks.iter().map(|(_, tokens)| tokens.len()).sum();
73	    let avg_doc_len = bm25::as_f64(total_tokens) / bm25::as_f64(corpus_size);
74	    let mut ranked: Vec<RankedBlock> = blocks
75	        .into_iter()
76	        .map(|(block, doc_tokens)| {
77	            let bm25_score = score(&doc_tokens, query_terms, avg_doc_len, corpus_size, df);
78	            let coverage_boost = coverage_boost(&block);
79	            let node_type_boost = node_type_boost(block.node_kind);
80	            let name_boost = name_match_boost(&block, query_terms);
81	            let parent_context = block.parent.clone();
82	            RankedBlock {
83	                block,
84	                bm25_score,
85	                coverage_boost,
86	                node_type_boost,
87	                final_score: round6(bm25_score * name_boost * node_type_boost + coverage_boost),
88	                rank: 0,
89	                parent_context,
90	            }
91	        })
92	        .collect();
93	    ranked.sort_by(best_first);
94	    for (rank, block) in (1..).zip(&mut ranked) {
95	        block.rank = rank;
96	    }
97	    ranked
98	}
99	
100	/// Orders ranked blocks best first by a total order over everything that tells two blocks apart: `final_score`
101	/// descending, then `file` (component-wise), `line_start`, `line_end`, `node_kind` and `code` ascending.
102	///
103	/// `-0.0` and `0.0` compare equal so the sign of a zero score cannot reorder blocks; every other score, NaN included,
104	/// follows [`f64::total_cmp`].
105	fn best_first(a: &RankedBlock, b: &RankedBlock) -> Ordering {
106	    score_order(b.final_score)
107	        .total_cmp(&score_order(a.final_score))
108	        .then_with(|| a.block.file.cmp(&b.block.file))
109	        .then_with(|| a.block.line_start.cmp(&b.block.line_start))
110	        .then_with(|| a.block.line_end.cmp(&b.block.line_end))
111	        .then_with(|| kind_order(a.block.node_kind).cmp(&kind_order(b.block.node_kind)))
112	        .then_with(|| a.block.code.cmp(&b.block.code))
113	}
114	
115	/// Maps `-0.0` to `0.0`, which [`f64::total_cmp`] would otherwise order below it.
116	fn score_order(score: f64) -> f64 {
117	    if score == 0.0 { 0.0 } else { score }
118	}
119	
120	/// Returns the position of `kind` in `SymbolKind`'s declaration order.
121	fn kind_order(kind: SymbolKind) -> u8 {
122	    match kind {
123	        SymbolKind::Function => 0,
124	        SymbolKind::Method => 1,
125	        SymbolKind::Constructor => 2,
126	        SymbolKind::Class => 3,
127	        SymbolKind::Struct => 4,
128	        SymbolKind::Enum => 5,
129	        SymbolKind::Interface => 6,
130	        SymbolKind::TypeAlias => 7,
131	        SymbolKind::Property => 8,
132	        SymbolKind::Field => 9,
133	        SymbolKind::Variable => 10,
134	        SymbolKind::Module => 11,
135	        SymbolKind::Impl => 12,
136	        SymbolKind::Macro => 13,
137	        SymbolKind::Other => 14,
138	    }
139	}
