291	/// One analyzer can own several languages (TypeScript's owns JavaScript too), so the `--language` filter goes by
292	/// extension.
293	fn has_language_extension(language: Language, path: &Utf8Path) -> bool {
294	    match language {
295	        Language::TypeScript => matches!(path.extension(), Some("ts" | "tsx" | "mts" | "cts")),
296	        Language::JavaScript => matches!(path.extension(), Some("js" | "jsx" | "mjs" | "cjs")),
297	        Language::Rust => path.extension() == Some("rs"),
298	        Language::Python => false,
299	    }
