/// A block of code matched by the search pipeline.
#[derive(Debug, Clone)]
pub struct CodeBlock {
    pub file: Utf8PathBuf,
    pub line_start: usize,
    pub line_end: usize,
    pub node_kind: SymbolKind,
    pub code: String,
    pub symbol_signature: Option<String>,
    pub matched_lines: Vec<usize>,
    pub matched_keywords: Vec<String>,
    /// The block this one is a member of, such as the class of a method; `None` for a top-level block.
    pub parent: Option<ParentContext>,
}

/// The symbol enclosing a [`CodeBlock`], such as the class or object literal a method block belongs to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParentContext {
    pub kind: SymbolKind,
    pub name: String,
    pub line: usize,
}

/// A [`CodeBlock`] with its ranking scores.
#[derive(Debug, Clone)]
pub struct RankedBlock {
    pub block: CodeBlock,
    pub bm25_score: f64,
    pub coverage_boost: f64,
    pub node_type_boost: f64,
    pub final_score: f64,
    pub rank: usize,
    pub parent_context: Option<ParentContext>,
}

/// The kind of a [`Diagnostic`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum DiagnosticKind {
    Degraded,
    Skipped,
    Warning,
    /// The file held bytes that are not UTF-8, so it was searched and extracted with each invalid sequence replaced by
    /// U+FFFD.
    LossyRead,
}

/// A non-fatal problem reported alongside a command's results.
#[derive(Debug, Clone)]
pub struct Diagnostic {
    pub kind: DiagnosticKind,
    pub path: Option<Utf8PathBuf>,
    pub message: String,
}

/// A single line matched by the text searcher.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LineHit {
    pub line_number: usize,
    pub text: String,
}

/// The language filter for the search command.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "cli", derive(clap::ValueEnum))]
#[non_exhaustive]
pub enum Language {
    #[cfg_attr(feature = "cli", value(name = "typescript"))]
    TypeScript,
    #[cfg_attr(feature = "cli", value(name = "javascript"))]
    JavaScript,
    #[cfg_attr(feature = "cli", value(name = "rust"))]
    Rust,
    #[cfg_attr(feature = "cli", value(name = "python"))]
    Python,
}

/// The search command's response.
#[derive(Debug, Clone)]
pub struct SearchResponse {
    pub results: Vec<RankedBlock>,
    pub total_blocks_before_truncation: usize,
    pub truncated: bool,
    pub total_bytes: usize,
    pub total_tokens: usize,
    pub diagnostics: Vec<Diagnostic>,
}

/// Keeps the longest rank-order prefix of `ranked` whose printed rows fit `budget` and reports what was cut.
///
/// `row_text` returns the text that is printed for one block; the byte and token caps count that text, not the block's
/// code. Blocks are never split or reordered. The cut falls at the first block that would break any of the three caps,
/// so a row larger than the whole byte budget leaves no results. `total_before` is the count the caller had before any
/// cap, which may exceed `ranked.len()` when an earlier stage already dropped candidates; the response is truncated
/// whenever fewer blocks are kept than that. `total_bytes` sums the kept rows' text length and `total_tokens` its
/// [`count_tokens`] count. `diagnostics` pass through untouched.
///
/// # Examples
///
/// ```
/// use monokl::budget::{apply_budget, Budget};
///
/// let response = apply_budget(Vec::new(), 0, &Budget::default(), |_| String::new(), Vec::new());
/// assert!(!response.truncated);
/// assert_eq!(response.total_blocks_before_truncation, 0);
/// ```
pub fn apply_budget(
    ranked: Vec<RankedBlock>,
    total_before: usize,
    budget: &Budget,
    row_text: impl Fn(&RankedBlock) -> String,
    diagnostics: Vec<Diagnostic>,
) -> SearchResponse {
    let mut kept = Vec::new();
    let mut total_bytes = 0usize;
    let mut total_tokens = 0usize;
    for block in ranked {
        if kept.len() >= budget.max_results {
            break;
        }
        let text = row_text(&block);
        let Some(next_bytes) = total_bytes.checked_add(text.len()).filter(|b| *b <= budget.max_bytes) else { break };
        let Some(next_tokens) = total_tokens.checked_add(count_tokens(&text)).filter(|t| *t <= budget.max_tokens)
        else {
            break;
        };
        total_bytes = next_bytes;
        total_tokens = next_tokens;
        kept.push(block);
    }

    let outcome = TruncationOutcome::new(kept, total_before);
    SearchResponse {
        total_blocks_before_truncation: outcome.total_before,
        truncated: outcome.truncated(),
        results: outcome.kept,
        total_bytes,
        total_tokens,
        diagnostics,
    }
}

