/// Keeps the longest rank-order prefix of `ranked` whose printed rows fit `budget` and reports what was cut.
///
/// `row_text` returns the text that is printed for one block; the byte and token caps count that text, not the block's
/// code. Blocks are never split or reordered. The cut falls at the first block that would break any of the three caps,
/// so a row larger than the whole byte budget leaves no results. `total_before` is the count the caller had before any
/// cap, which may exceed `ranked.len()` when an earlier stage already dropped candidates; the response is truncated
/// whenever fewer blocks are kept than that. `total_bytes` sums the kept rows' text length and `total_tokens` its
/// [`count_tokens`] count. `diagnostics` pass through untouched.
///
/// # Examples
///
    }

    #[test]
    fn survivors_keep_every_field_but_rank() {
        let mut first = ranked("a.ts", 10, 20, 7);
        first.block.node_kind = SymbolKind::Class;
        first.block.code = "class A {}".to_string();
        first.block.symbol_signature = Some("class A".to_string());
        first.block.matched_lines = vec![11, 12];
        first.block.matched_keywords = vec!["a".to_string()];
        first.bm25_score = 1.25;
        first.coverage_boost = 0.5;
        first.node_type_boost = 1.4;
        first.final_score = 2.25;
        first.parent_context =
            Some(crate::types::ParentContext { kind: SymbolKind::Module, name: "m".to_string(), line: 1 });
        let duplicate = ranked("a.ts", 12, 18, 8);
        let mut other = ranked("b.ts", 1, 3, 9);
        other.block.code = "fn b() {}".to_string();
        other.final_score = 0.75;

        let out = dedup_blocks(vec![first.clone(), duplicate, other.clone()]);
        let fields = |r: &RankedBlock| {
            let b = &r.block;
            let parent = r.parent_context.as_ref().map(|p| (p.kind, p.name.clone(), p.line));
            // Two tuples: std implements PartialEq and Debug for tuples of at most 12 elements.
            (
                (b.file.clone(), b.line_start, b.line_end, b.node_kind, b.code.clone(), b.symbol_signature.clone()),
                (
                    b.matched_lines.clone(),
                    b.matched_keywords.clone(),
                    r.bm25_score.to_bits(),
                    r.coverage_boost.to_bits(),
                    r.node_type_boost.to_bits(),
                    r.final_score.to_bits(),
                    parent,
                ),
            )
        };
        assert_eq!(out.iter().map(|r| r.rank).collect::<Vec<_>>(), [1, 2]);
        assert_eq!(out.iter().map(fields).collect::<Vec<_>>(), [fields(&first), fields(&other)]);
    }

    rows.sort();
    assert_eq!(rows, [(1, 9, vec![2], false), (3, 5, vec![4], true)]);
}

#[test]
fn a_member_row_is_ranked_with_the_kind_boost_of_its_own_kind() {
    let dir = project(&[("src/foo.ts", FOO)]);
    let result = library_search(&dir, "loadUser");
    let ranked = &result.ranked[0];
    assert_eq!(
        (
            ranked.block.node_kind,
            ranked.node_type_boost,
            ranked.rank,
            ranked.parent_context.as_ref().map(|p| p.name.as_str())
        ),
        (monokl::types::SymbolKind::Method, 1.4, 1, Some("Foo"))
    );
}

/// An object literal with a data property, two functions, an accessor and a member too short to get a block.
    }

    #[test]
    fn blocks_are_ranked_by_bm25_over_literal_term_tokens() {
        let (_dir, root) = tree(&[
            ("weak.ts", "getUserName(alpha, bravo, charlie)\n"),
            ("strong.ts", "getUserName()\n"),
            ("none.ts", "GETUSERNAME\n"),
        ]);
        let result = search(&whole_file_registry(), &request(&root, "getUserName")).unwrap();
        assert_eq!(files(&result, &root), ["strong.ts", "weak.ts", "none.ts"]);
        let ranks: Vec<usize> = result.ranked.iter().map(|r| r.rank).collect();
        assert_eq!(ranks, [1, 2, 3]);
        assert!(result.ranked[0].bm25_score > result.ranked[1].bm25_score);
        assert!(result.ranked[1].bm25_score > result.ranked[2].bm25_score);
        assert!(result.ranked[2].bm25_score.abs() < f64::EPSILON);
    }

    #[test]
    fn regex_terms_add_no_bm25_terms() {
        let (_dir, root) = tree(&[("a.ts", "getUserName()\n")]);
        let result = search(&whole_file_registry(), &request(&root, "regex:getUser")).unwrap();
        assert_eq!(result.ranked.len(), 1);
        assert!(result.ranked[0].bm25_score.abs() < f64::EPSILON);
    }

    #[test]
    fn bm25_terms_are_unique_lowercase_tokens_of_non_excluded_literals() {
        let plan = QueryPlan::from_terms(parse("getUserName +userId -secretKey regex:Foo+ user").unwrap());
        assert_eq!(bm25_terms(&plan), ["user", "name", "id"]);
    }

