import subprocess, sys
root = sys.argv[1]
old, new = sys.argv[2], sys.argv[3]
qs = []
for line in open(root + '/scripts/rg-compare.questions'):
    if line.startswith('#') or '|' not in line:
        continue
    cells = [c.strip() for c in line.split('|')]
    qs.append((cells[0], cells[1]))
for repo, sym in [('zod', 'ZodType'), ('zod', 'parse'), ('axios', 'request'), ('fd', 'filter'), ('trpc', 'router')]:
    qs.append((repo, sym))
def run(binary, repo, q):
    return subprocess.run([binary, 'search', q, 'target/rg-compare/' + repo], cwd=root, capture_output=True, text=True).stdout.splitlines()
bad = rows = maxdev = 0
for repo, q in qs:
    a, b = run(old, repo, q), run(new, repo, q)
    if len(a) != len(b):
        print('LEN', repo, q); bad += 1; continue
    for x, y in zip(a, b):
        if x.startswith('  ') and y.startswith('  '):
            xa, xs = x.rsplit(',', 1); ya, ys = y.rsplit(',', 1)
            dev = abs(float(xs) - 1.0 - float(ys))
            maxdev = max(maxdev, dev); rows += 1
            if xa != ya or dev > 1.1e-6:
                print('DIFF', repo, q, x[:80]); bad += 1
        elif x != y:
            print('DIFF', repo, q, x[:80], y[:80]); bad += 1
print('queries', len(qs), 'rows', rows, 'bad', bad, 'maxdev', maxdev)
sys.exit(1 if bad else 0)

